<!-- Generated by design-ui/bin/generate-review-demos.mjs; fixture: error.vue. Edit the authored scenario, then regenerate. -->
<script setup lang="ts">
import { computed, onBeforeUnmount, onDeactivated, ref } from 'vue'
import { watchLang } from '@maple-design/cli/client'
import type { InfiniteScrollStatus } from '@maple-design/ui'
import { defineReviewConfig, ReviewSlot as DemoReviewSlot } from '@sparknest/ui-doc-preview'
import DemoApiReviewPanel from '../../../../docs/components/ApiReviewPanel.vue'
import __apiReviewRawConfig from './api-review-mp-infinite-scroll-2.config.json'

const scroller = ref<HTMLElement>()
const status = ref<InfiniteScrollStatus>('idle')
const items = ref<number[]>([])
let failedOnce = false
let timer: ReturnType<typeof setTimeout> | undefined
const language = ref('zh-CN')
const english = computed(() => language.value === 'en-US')

watchLang((value) => {
  language.value = value
})

function load() {
  clearTimeout(timer)
  timer = setTimeout(() => {
    timer = undefined
    if (!failedOnce && items.value.length >= 12) {
      failedOnce = true
      status.value = 'error'
      return
    }
    for (let index = 0; index < 12; index++) {
      items.value.push(items.value.length + 1)
    }
    status.value = items.value.length >= 48 ? 'finished' : 'idle'
  }, 500)
}
onBeforeUnmount(() => clearTimeout(timer))
onDeactivated(() => {
  clearTimeout(timer)
  timer = undefined
  if (status.value === 'loading') {
    status.value = 'idle'
  }
})
</script>

<template>
  <DemoApiReviewPanel v-slot="__apiReview" v-bind="defineReviewConfig(__apiReviewRawConfig)">
    <div ref="scroller" class="infinite-scroll-demo">
      <mp-infinite-scroll
        v-model:status="status"
        :target="scroller"
        v-bind="__apiReview.bindings"
        @load="load"
        @retry="load"
        v-on="__apiReview.listeners"
      >
        <mp-cell v-for="item in items" :key="item">{{ english ? 'List item' : '列表项' }} {{ item }}</mp-cell>
        <template v-if="__apiReview.slotEnabled['error'] !== false" #error="{ retry }">
          {{ english ? 'Load failed.' : '加载失败，' }}
          <mp-button variant="text" size="sm" status="primary" @click="retry">{{
            english ? 'Try again' : '点击重试'
          }}</mp-button>
        </template>
        <template v-if="__apiReview.slotEnabled['loading']" #loading="__reviewSlot"
          ><DemoReviewSlot
            name="loading"
            :context="__reviewSlot"
            :controls="__apiReview.controls"
            :record="__apiReview.record"
        /></template>
        <template v-if="__apiReview.slotEnabled['finished']" #finished="__reviewSlot"
          ><DemoReviewSlot
            name="finished"
            :context="__reviewSlot"
            :controls="__apiReview.controls"
            :record="__apiReview.record" /></template
      ></mp-infinite-scroll>
    </div>
  </DemoApiReviewPanel>
</template>

